CREATE TABLE public.integrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), description text NOT NULL DEFAULT '' CHECK(length(description)<=2000), active boolean NOT NULL DEFAULT true, company_scope text NOT NULL CHECK(company_scope IN ('all','selected')), created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
GRANT SELECT ON public.integrations TO authenticated; GRANT ALL ON public.integrations TO service_role;
ALTER TABLE public.integrations ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrations_read ON public.integrations FOR SELECT TO authenticated USING(public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE TABLE public.integration_companies(integration_id uuid NOT NULL,company_id uuid NOT NULL,organization_id uuid NOT NULL,PRIMARY KEY(integration_id,company_id),FOREIGN KEY(integration_id,organization_id) REFERENCES public.integrations(id,organization_id),FOREIGN KEY(company_id,organization_id) REFERENCES public.companies(id,organization_id));
GRANT SELECT ON public.integration_companies TO authenticated; GRANT ALL ON public.integration_companies TO service_role;
ALTER TABLE public.integration_companies ENABLE ROW LEVEL SECURITY;
CREATE POLICY integration_companies_read ON public.integration_companies FOR SELECT TO authenticated USING(public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE TABLE public.integration_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),integration_id uuid NOT NULL,organization_id uuid NOT NULL,environment public.environment NOT NULL,key_prefix text NOT NULL,key_hash text NOT NULL UNIQUE CHECK(key_hash ~ '^[a-f0-9]{64}$'),created_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz,revoked_at timestamptz,revoked_by uuid REFERENCES public.profiles(id),FOREIGN KEY(integration_id,organization_id) REFERENCES public.integrations(id,organization_id),UNIQUE(id,integration_id,organization_id,environment),CHECK((environment='sandbox' AND key_prefix LIKE 'ntm_homolog_%') OR (environment='production' AND key_prefix LIKE 'ntm_prod_%')));
GRANT SELECT(id,integration_id,organization_id,environment,key_prefix,created_by,created_at,last_used_at,revoked_at,revoked_by) ON public.integration_keys TO authenticated; GRANT ALL ON public.integration_keys TO service_role;
ALTER TABLE public.integration_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY integration_keys_read ON public.integration_keys FOR SELECT TO authenticated USING(public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE TABLE public.api_request_logs(id text PRIMARY KEY CHECK(id ~ '^req_[a-f0-9]{32}$'),organization_id uuid REFERENCES public.organizations(id),integration_id uuid,key_id uuid,environment public.environment,method text NOT NULL CHECK(length(method)<=16),path text NOT NULL CHECK(length(path)<=2048),status_code integer NOT NULL CHECK(status_code BETWEEN 100 AND 599),error_code text,duration_ms integer NOT NULL CHECK(duration_ms>=0),request_body jsonb,response_body jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(integration_id,organization_id) REFERENCES public.integrations(id,organization_id),FOREIGN KEY(key_id,integration_id,organization_id,environment) REFERENCES public.integration_keys(id,integration_id,organization_id,environment),CHECK(request_body IS NULL OR octet_length(request_body::text)<=65536),CHECK(response_body IS NULL OR octet_length(response_body::text)<=65536));
GRANT SELECT ON public.api_request_logs TO authenticated; GRANT ALL ON public.api_request_logs TO service_role;
ALTER TABLE public.api_request_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY api_logs_read ON public.api_request_logs FOR SELECT TO authenticated USING(created_at>=now()-interval '90 days' AND (public.is_org_member(organization_id) OR public.is_platform_admin()));
CREATE INDEX integration_keys_active ON public.integration_keys(integration_id,environment) WHERE revoked_at IS NULL;
CREATE INDEX api_logs_integration_date ON public.api_request_logs(integration_id,created_at DESC); CREATE INDEX api_logs_org_date ON public.api_request_logs(organization_id,created_at DESC); CREATE INDEX api_logs_expiration ON public.api_request_logs(created_at);
CREATE FUNCTION public.guard_integration_records() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_TABLE_NAME='integrations' THEN IF TG_OP='UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN RAISE EXCEPTION 'Organização imutável'; END IF; NEW.updated_at=now();
ELSIF TG_TABLE_NAME='integration_companies' THEN PERFORM 1 FROM public.integrations WHERE id=NEW.integration_id AND company_scope='selected' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Escopo deve ser selected'; END IF;
ELSIF TG_TABLE_NAME='integration_keys' THEN PERFORM 1 FROM public.integrations WHERE id=NEW.integration_id FOR UPDATE; IF TG_OP='UPDATE' AND (NEW.integration_id,NEW.organization_id,NEW.environment,NEW.key_hash,NEW.key_prefix,NEW.revoked_at IS NULL) IS DISTINCT FROM (OLD.integration_id,OLD.organization_id,OLD.environment,OLD.key_hash,OLD.key_prefix,OLD.revoked_at IS NULL) AND NOT(OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL AND NEW.integration_id=OLD.integration_id AND NEW.organization_id=OLD.organization_id AND NEW.environment=OLD.environment AND NEW.key_hash=OLD.key_hash AND NEW.key_prefix=OLD.key_prefix) THEN RAISE EXCEPTION 'Chave imutável'; END IF; IF TG_OP='INSERT' AND NEW.revoked_at IS NULL AND (SELECT count(*) FROM public.integration_keys WHERE integration_id=NEW.integration_id AND environment=NEW.environment AND revoked_at IS NULL)>=2 THEN RAISE EXCEPTION 'Máximo de duas chaves ativas por ambiente'; END IF;
END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_integration_records() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER integration_guard BEFORE INSERT OR UPDATE ON public.integrations FOR EACH ROW EXECUTE FUNCTION public.guard_integration_records();
CREATE TRIGGER integration_company_guard BEFORE INSERT OR UPDATE ON public.integration_companies FOR EACH ROW EXECUTE FUNCTION public.guard_integration_records();
CREATE TRIGGER integration_key_guard BEFORE INSERT OR UPDATE ON public.integration_keys FOR EACH ROW EXECUTE FUNCTION public.guard_integration_records();
CREATE FUNCTION public.manage_integration(_actor uuid,_org uuid,_action text,_id uuid,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE result_id uuid; item text; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.platform_admins WHERE user_id=_actor) AND NOT EXISTS(SELECT 1 FROM public.organization_members WHERE user_id=_actor AND organization_id=_org AND role IN ('owner','admin','developer')) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF;
IF _action='save' THEN
IF _id IS NULL THEN INSERT INTO public.integrations(organization_id,name,description,active,company_scope,created_by) VALUES(_org,_payload->>'name',coalesce(_payload->>'description',''),coalesce((_payload->>'active')::boolean,true),_payload->>'company_scope',_actor) RETURNING id INTO result_id;
ELSE PERFORM 1 FROM public.integrations WHERE id=_id AND organization_id=_org FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Integração não encontrada'; END IF; result_id=_id; DELETE FROM public.integration_companies WHERE integration_id=_id; UPDATE public.integrations SET name=_payload->>'name',description=coalesce(_payload->>'description',''),active=(_payload->>'active')::boolean,company_scope=_payload->>'company_scope' WHERE id=_id; END IF;
IF _payload->>'company_scope'='selected' THEN IF jsonb_array_length(coalesce(_payload->'company_ids','[]'::jsonb))=0 THEN RAISE EXCEPTION 'Selecione ao menos uma empresa'; END IF; FOR item IN SELECT jsonb_array_elements_text(_payload->'company_ids') LOOP INSERT INTO public.integration_companies VALUES(result_id,item::uuid,_org); END LOOP; END IF;
ELSIF _action IN ('generate','revoke') THEN PERFORM 1 FROM public.integrations WHERE id=_id AND organization_id=_org FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Integração não encontrada'; END IF; result_id=_id;
IF _action='generate' THEN INSERT INTO public.integration_keys(integration_id,organization_id,environment,key_prefix,key_hash,created_by) VALUES(_id,_org,(_payload->>'environment')::public.environment,_payload->>'key_prefix',_payload->>'key_hash',_actor);
ELSE UPDATE public.integration_keys SET revoked_at=now(),revoked_by=_actor WHERE id=(_payload->>'key_id')::uuid AND integration_id=_id AND revoked_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Chave não encontrada ou já revogada'; END IF; END IF;
ELSE RAISE EXCEPTION 'Operação inválida'; END IF; RETURN result_id; END $$;
REVOKE ALL ON FUNCTION public.manage_integration(uuid,uuid,text,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.manage_integration(uuid,uuid,text,uuid,jsonb) TO service_role;